```json
{
  "root_causes": [
    {
      "service": "reservation",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT 'abn' AS p, count(*) AS n FROM abnormal_metrics WHERE service_name='reservation' UNION ALL SELECT 'norm' AS p, count(*) AS n FROM normal_metrics WHERE service_name='reservation'",
          "claim": "Reservation pod emits no metrics during the incident window, while the normal period has over a thousand rows."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abn' AS p, count(*) AS n FROM abnormal_traces WHERE service_name='reservation' UNION ALL SELECT 'norm' AS p, count(*) AS n FROM normal_traces WHERE service_name='reservation'",
          "claim": "Reservation service has zero server spans in the incident, versus 2004 in the normal period."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) AS n FROM abnormal_traces WHERE span_name='reservation.Reservation/CheckAvailability' GROUP BY 1,2,3",
          "claim": "Every CheckAvailability call from frontend in the incident is an Error span, with no matching reservation server span."
        },
        {
          "kind": "log",
          "sql": "SELECT count(*) AS n FROM abnormal_logs WHERE service_name='frontend' AND level='ERROR' AND message='Reservation check availability failed'",
          "claim": "Frontend logs hundreds of 'Reservation check availability failed' errors during the incident window."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "reservation",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT date_trunc('minute', time) AS m, count(*) AS hotels_requests, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS hotels_errors FROM abnormal_traces WHERE span_name='HTTP /hotels' GROUP BY 1 ORDER BY 1",
          "claim": "From 11:49 onward every frontend HTTP /hotels request returns 500, after its reservation call fails."
        }
      ]
    }
  ]
}
```

